ALTER TABLE profiles ADD COLUMN avatar_url text,ADD COLUMN is_vip boolean DEFAULT false;
ALTER TABLE agents ADD COLUMN role text DEFAULT 'agent';
ALTER TABLE social_messages ADD COLUMN created_at timestamptz DEFAULT now(),ADD COLUMN updated_at timestamptz,ADD COLUMN is_deleted boolean DEFAULT false,ADD COLUMN is_edited boolean DEFAULT false;
ALTER TABLE notifications ADD COLUMN is_read boolean DEFAULT false,ADD COLUMN read_at timestamptz;
ALTER TABLE chip_ledger ADD COLUMN settlement_id text;
CREATE TABLE union_wallets(id uuid,union_id uuid);
CREATE TABLE settlement_periods(id uuid PRIMARY KEY,club_id uuid,union_id uuid,start_at timestamptz,end_at timestamptz,status text);
CREATE TABLE ca_settlements(id uuid PRIMARY KEY,settlement_type text,union_id uuid,state text,external_ref text,totals jsonb);
CREATE TABLE union_clubs(union_id uuid,club_id uuid);
CREATE TABLE union_accounting_runs(union_id uuid,period_start timestamptz,period_end timestamptz,status text);
CREATE TABLE ca_money_rpc_registry(proname text PRIMARY KEY,status text,notes text);
CREATE FUNCTION u(n int) RETURNS uuid LANGUAGE sql IMMUTABLE AS $$SELECT ('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
